	traverser(C).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 3) % n_len) / m_len;
	});
}

// computation kernel
// BLAS-like SYR2K:
//
// C := alpha * A * B^T + alpha * B * A^T + beta * C
//
// with:
//   A: N x M
//   B: N x M
//   C: N x N (only lower-triangular part (i,j) with j <= i is updated)
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

	// C: i x j
	// A: i x k
	// B: i x k

#pragma scop
	// ---------------------------------------------------------------------
	// 1) Scale only the lower-triangular part of C by beta:
	//    for (i = 0; i < N; ++i)
	//      for (j = 0; j <= i; ++j)
	//        C[i][j] *= beta;
	//
	// Instead of iterating the full matrix and branching on (j <= i),
	// we restrict the traversal in 'j' using noarr::slice so that only
	// the relevant triangular range is visited. This removes a branch
	// and halves the number of iterations over C.
	// ---------------------------------------------------------------------
	traverser(C).template for_dims<'i'>([&](auto trav_i) {
		// i is fixed in trav_i
		auto state_i = trav_i.state();
		std::size_t i_idx = get_index<'i'>(state_i);

		// Restrict j to 0..i_idx (length = i_idx + 1).
		// We create a new traverser view that only iterates this slice.
		auto trav_ij = trav_i.order(slice<'j'>(0, i_idx + 1));

		trav_ij.for_each([&](auto state) {
			// state has (i, j) with j in [0, i]
			C[state] *= beta;
		});
	});

	// ---------------------------------------------------------------------
	// 2) SYR2K update:
	//
	//   for (i = 0; i < N; ++i)
	//     for (k = 0; k < M; ++k) {
	//       const num_t Aik = A[i][k];
	//       const num_t Bik = B[i][k];
	//       for (j = 0; j <= i; ++j)
	//         C[i][j] += alpha * ( A[j][k] * B[i][k] + B[j][k] * A[i][k] );
	//     }
	//
	// We implement the same iteration order using Noarr traversers:
	//  - outer for_dims<'i','k'> reproduces the (i,k) loops
	//  - inner for_each over a sliced 'j' dimension enforces j <= i
	//
	// Additionally:
	//  - A[i][k] and B[i][k] are hoisted out of the inner j-loop
	//  - we precompute alpha * A[i][k] and alpha * B[i][k] once per (i,k),
	//    reducing one multiplication per inner iteration.
	// ---------------------------------------------------------------------
	traverser(C, A, B).template for_dims<'i', 'k'>([&](auto trav_ik) {
		// (i, k) are fixed in trav_ik
		auto state_ik = trav_ik.state();
		std::size_t i_idx = get_index<'i'>(state_ik);
		std::size_t k_idx = get_index<'k'>(state_ik);

		// A[i][k] and B[i][k] are reused for all j in [0, i]
		const num_t Aik = A[state_ik];
		const num_t Bik = B[state_ik];

		// Pre-scale by alpha once per (i,k):
		// alpha * (A[j][k] * B[i][k] + B[j][k] * A[i][k])
		//   = (alpha * B[i][k]) * A[j][k] + (alpha * A[i][k]) * B[j][k]
		const num_t alphaAik = alpha * Aik;
		const num_t alphaBik = alpha * Bik;

