			// state has (i, j, k) with 0 <= j <= i
			std::size_t j_idx = get_index<'j'>(state);

			// Build a state for A[j][k] and B[j][k]:
			//   - dimension 'i' is used as the row index for A/B
			//   - dimension 'k' is the column index
			auto state_jk = idx<'i', 'k'>(j_idx, k_idx);

			const num_t Ajk = A[state_jk];
			const num_t Bjk = B[state_jk];

			// Reference to C[i][j]; 'k' in the state is ignored by C.
			num_t &Cij = C[state];

			// C[i][j] += alpha * ( A[j][k] * B[i][k] + B[j][k] * A[i][k] );
			// Using pre-scaled alphaBik = alpha * B[i][k], alphaAik = alpha * A[i][k]:
			//   = alphaBik * A[j][k] + alphaAik * B[j][k]
			Cij += alphaBik * Ajk + alphaAik * Bjk;
		});
	});
