using num_t = DATA_TYPE;

namespace {

// basic dimension proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();
constexpr auto k_vec = noarr::vector<'k'>();

// layout tuning (can be changed independently of the algorithm)
struct tuning {
	// C is N x N, indexed by (i, j)
	DEFINE_PROTO_STRUCT(c_layout, j_vec ^ i_vec); // physical layout: j (inner) x i (outer) – row-major in (i, j)

	// A is N x M, indexed by (i, k)
	DEFINE_PROTO_STRUCT(a_layout, k_vec ^ i_vec); // physical layout: k (inner) x i (outer) – row-major in (i, k)

	// B is N x M, indexed by (i, k)
	DEFINE_PROTO_STRUCT(b_layout, k_vec ^ i_vec); // physical layout: k (inner) x i (outer) – row-major in (i, k)
} tuning;

// initialization function
// C: i x j  (N x N)
// A: i x k  (N x M)
// B: i x k  (N x M)
void init_array(num_t &alpha, num_t &beta, auto C, auto A, auto B) {
	using namespace noarr;

	alpha = (num_t)1.5;
	beta  = (num_t)1.2;

	// Query lengths once, outside the element-wise lambdas, so the compiler
	// can treat them as loop-invariant and potentially constant-fold them.
	const std::size_t n_len = A | get_length<'i'>(); // corresponds to original 'n'
	const std::size_t m_len = A | get_length<'k'>(); // corresponds to original 'm'

	// Initialize A: A[i][k] = ( (i * k + 1) % n ) / n
	traverser(A).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		A[state] = (num_t)((i * k + 1) % n_len) / (num_t)n_len;
	});

	// Initialize B: B[i][k] = ( (i * k + 2) % m ) / m
	traverser(B).for_each([=](auto state) {
		auto [i, k] = get_indices<'i', 'k'>(state);
		B[state] = (num_t)((i * k + 2) % m_len) / (num_t)m_len;
	});

	// Initialize C: C[i][j] = ( (i * j + 3) % n ) / m
	const std::size_t nC_len = C | get_length<'i'>(); // N (should equal n_len)
	traverser(C).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		C[state] = (num_t)((i * j + 3) % nC_len) / (num_t)m_len;
	});
}

// computation kernel
// BLAS-like SYR2K:
//
// C := alpha * A * B^T + alpha * B * A^T + beta * C
//
// with:
//   A: N x M
//   B: N x M
//   C: N x N (only lower-triangular part (i,j) with j <= i is updated)
//
// The implementation below keeps the original computation order for the k-loop
// (to preserve floating-point accumulation order), but:
//   - removes inner-branching on j<=i by traversing only the lower triangle,
//   - hoists loop-invariant quantities (A[i][k], B[i][k], alpha*...),
//   - minimizes state manipulation when accessing A[j][k], B[j][k],
//   - preserves the original algebraic expression exactly.
[[gnu::flatten, gnu::noinline]]
void kernel_syr2k(num_t alpha, num_t beta, auto C, auto A, auto B) {
	using namespace noarr;

#pragma scop
	// ---------------------------------------------------------------------
	// 1) Scale the lower-triangular part of C by beta:
	//    for (i = 0; i < N; ++i)
	//      for (j = 0; j <= i; ++j)
	//        C[i][j] *= beta;
	//
	// Implemented using a 1D view of each row i (fix<'i'>) and a slice in 'j'
	// to avoid the j<=i branch inside the innermost loop.
	// ---------------------------------------------------------------------
	{
		auto C_ref = C.get_ref(); // copyable reference bag

		traverser(C_ref).template for_dims<'i'>([&](auto trav_i) {
			const std::size_t i = get_index<'i'>(trav_i.state());

			// View of row i, only dimension 'j' remains.
			auto C_row = C_ref ^ fix<'i'>(i);

			// Traverse j in [0, i] (i+1 elements), i.e. exactly the lower
			// triangular part for this row.
			auto row_trav = traverser(C_row).order(slice<'j'>(std::size_t(0), i + 1));

			row_trav.for_each([&](auto state_j) {
				C_row[state_j] *= beta;
			});
		});
	}

	// ---------------------------------------------------------------------
	// 2) Rank-2k update on the lower triangle:
	//
	//   for (i = 0; i < N; ++i)
	//     for (k = 0; k < M; ++k) {
	//       A_ik = A[i][k];
	//       B_ik = B[i][k];
	//       for (j = 0; j <= i; ++j) {
	//         A_jk = A[j][k];
	//         B_jk = B[j][k];
	//         C[i][j] += A_jk * alpha * B_ik + B_jk * alpha * A_ik;
	//       }
	//     }
	//
	// We keep the (i,k,j) nesting to preserve the original accumulation
	// order, but:
	//   - reuse a row view / triangular traverser for j (no inner branch),
	//   - hoist A[i][k], B[i][k] and their alpha-scaled variants out of
	//     the j-loop, reducing multiplications,
	//   - use a minimal state for A[j][k], B[j][k] (idx<'i','k'>(j,k)),
	//   - reconstruct the (i,j) state for C from the row-local state.
	// ---------------------------------------------------------------------
	traverser(C, A, B).template for_dims<'i'>([&](auto trav_i) {
		const std::size_t i = get_index<'i'>(trav_i.state());

		// Reuse the same row view and triangular traverser for all k in this i.
		auto C_row = C.get_ref() ^ fix<'i'>(i); // only 'j' dimension
		auto row_trav = traverser(C_row).order(slice<'j'>(std::size_t(0), i + 1));

		// Loop over k using the shared traverser; state here has dimensions 'i' and 'k'.
		trav_i.template for_dims<'k'>([&](auto trav_k) {
			auto state_ik = trav_k.state();
			const std::size_t k = get_index<'k'>(state_ik);

			// Load elements that depend only on (i, k) once per j-loop.
			const num_t A_ik = A[state_ik];
